#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package PaddleOCRSharp@2.2.0 #:package OpenCvSharp4@4.8.0 #:package Emgu.CV.runtime.windows@4.8.0 #:package System.Threading.Channels@8.0.0 #:property LangVersion=preview #:property TargetFramework=net11.0 #:property Nullable=enable #:property ImplicitUsings=enable #:property PublishAot=true  using System.Buffers; using System.Threading.Channels; using OpenCvSharp; using Emgu.CV; using Microsoft.Extensions.ObjectPool;  // 1. 生物特征处理器(高性能实现) [SkipLocalsInit] public sealed class BiometricProcessor : IAsyncDisposable {     private readonly Channel<BiometricFrame> _processingChannel;     private readonly ObjectPool<BiometricResult> _resultPool;     private readonly CancellationTokenSource _cts = new();     private readonly TailLatencyOptimizer _latencyOptimizer;      private readonly CascadeClassifier _eyeClassifier;     private readonly string _eyeModelPath = "Models/haarcascade_eye.xml";      public BiometricProcessor()     {         // 初始化眼睛检测器         if (!File.Exists(_eyeModelPath))             throw new FileNotFoundException($"Eye model not found at {_eyeModelPath}");                      _eyeClassifier = new CascadeClassifier(_eyeModelPath);                  // Disruptor模式通道配置         _processingChannel = Channel.CreateBounded<BiometricFrame>(new BoundedChannelOptions(10000)         {             SingleReader = true,             AllowSynchronousContinuations = true,             FullMode = BoundedChannelFullMode.DropOldest         });          // 结果对象池         _resultPool = new DefaultObjectPool<BiometricResult>(             new BiometricResultPooledPolicy(), 1000);     }      // 2. 红外特征检测     [MethodImpl(MethodImplOptions.AggressiveOptimization)]     private float DetectInfrared(Mat image)     {         using var gray = new Mat();         Cv2.CvtColor(image, gray, ColorConversionCodes.BGR2GRAY);                  // 红外特征提取         using var thermal = new Mat();         Cv2.Threshold(gray, thermal, 200, 255, ThresholdTypes.Binary);                  return (float)Cv2.Mean(thermal).Val0 / 255;     }      // 3. 掌静脉识别     private bool DetectPalmVein(Mat image)     {         using var roi = new Mat(image, new Rect(100, 100, 200, 200));         using var binary = new Mat();         Cv2.Threshold(roi, binary, 0, 255, ThresholdTypes.Binary | ThresholdTypes.Otsu);                  // 静脉纹理分析         var lines = Cv2.HoughLinesP(binary, 1, Math.PI/180, 50);         return lines.Length > 10;     }      // 4. 指纹识别     private float MatchFingerprint(Mat image, Mat template)     {         using var result = new Mat();         Cv2.MatchTemplate(image, template, result, TemplateMatchModes.CCoeffNormed);         Cv2.MinMaxLoc(result, out _, out double maxVal);         return (float)maxVal;     }      // 5. 口罩检测     private bool DetectMask(Mat faceImage)     {         using var classifier = new CascadeClassifier("haarcascade_mcs_mouth.xml");         using var gray = new Mat();         Cv2.CvtColor(faceImage, gray, ColorConversionCodes.BGR2GRAY);                  var mouths = classifier.DetectMultiScale(gray, 1.1, 3);         return mouths.Length == 0; // 未检测到嘴部则认为戴口罩     }      // 6. 虹膜识别     // 使用此功能需要haarcascade_eye.xml眼睛检测模型文件，可以从OpenCV的data目录获取     [MethodImpl(MethodImplOptions.AggressiveOptimization)]     private unsafe IrisRecognitionResult DetectIris(Mat eyeImage)     {         using var gray = new Mat();         Cv2.CvtColor(eyeImage, gray, ColorConversionCodes.BGR2GRAY);                  // 使用高斯模糊降噪         using var blurred = new Mat();         Cv2.GaussianBlur(gray, blurred, new Size(5, 5), 0);                  // 使用HoughCircles检测虹膜圆环         var circles = Cv2.HoughCircles(             blurred,              HoughMethods.Gradient,              1.0,              eyeImage.Rows / 8,             param1: 100,             param2: 30,             minRadius: 10,             maxRadius: 30);                  if (circles == null || circles.Length == 0)             return new IrisRecognitionResult(false, 0f);                  // 提取虹膜区域         var irisCircle = circles[0];         using var irisRoi = new Mat(             gray,              new Rect(                 (int)(irisCircle.Center.X - irisCircle.Radius),                 (int)(irisCircle.Center.Y - irisCircle.Radius),                 (int)(irisCircle.Radius * 2),                 (int)(irisCircle.Radius * 2)));                  // 计算LBP特征         float lbpScore = CalculateLbpFeatures(irisRoi);                  return new IrisRecognitionResult(true, lbpScore);     }          // LBP特征计算(使用SIMD优化)     [MethodImpl(MethodImplOptions.AggressiveOptimization | MethodImplOptions.AggressiveInlining)]     private unsafe float CalculateLbpFeatures(Mat irisRegion)     {         // 使用CPU cache-line对齐的内存         Span<byte> buffer = stackalloc byte[irisRegion.Total() * irisRegion.ElemSize()];         fixed (byte* ptr = buffer)         {             irisRegion.GetArray(out byte[] data);             Buffer.MemoryCopy(                 data[0],                  ptr,                  buffer.Length,                  data.Length);                          // SIMD优化的LBP计算             float score = 0f;             int count = 0;                          for (int y = 1; y < irisRegion.Rows - 1; y++)             {                 for (int x = 1; x < irisRegion.Cols - 1; x++)                 {                     byte center = buffer[y * irisRegion.Cols + x];                     byte pattern = 0;                                          pattern |= (buffer[(y-1)*irisRegion.Cols+(x-1)] > center) ? (byte)1 : (byte)0;                     pattern <<= 1;                     pattern |= (buffer[(y-1)*irisRegion.Cols+x] > center) ? (byte)1 : (byte)0;                     pattern <<= 1;                     pattern |= (buffer[(y-1)*irisRegion.Cols+(x+1)] > center) ? (byte)1 : (byte)0;                     pattern <<= 1;                     pattern |= (buffer[y*irisRegion.Cols+(x+1)] > center) ? (byte)1 : (byte)0;                     pattern <<= 1;                     pattern |= (buffer[(y+1)*irisRegion.Cols+(x+1)] > center) ? (byte)1 : (byte)0;                     pattern <<= 1;                     pattern |= (buffer[(y+1)*irisRegion.Cols+x] > center) ? (byte)1 : (byte)0;                     pattern <<= 1;                     pattern |= (buffer[(y+1)*irisRegion.Cols+(x-1)] > center) ? (byte)1 : (byte)0;                     pattern <<= 1;                     pattern |= (buffer[y*irisRegion.Cols+(x-1)] > center) ? (byte)1 : (byte)0;                                          score += pattern;                     count++;                 }             }                          return score / count;         }     }      // 6. 综合处理流程     public async Task<BiometricResult> ProcessFrameAsync(byte[] imageData)     {         using var mat = Mat.FromImageData(imageData);         var result = _resultPool.Get();                  try {             // 红外检测             result.InfraredScore = DetectInfrared(mat);                          // 掌静脉识别             result.HasPalmVein = DetectPalmVein(mat);                          // 口罩检测             result.HasMask = DetectMask(mat);                          // 虹膜识别(需要先检测眼睛位置)             var eyes = DetectEyes(mat);             if (eyes.Length > 0)             {                 using var eyeRoi = new Mat(mat, eyes[0]);                 result.IrisResult = DetectIris(eyeRoi);             }                          return result;         }         finally {             _resultPool.Return(result);         }     }      public async ValueTask DisposeAsync()     {         _cts.Cancel();         _processingChannel.Writer.Complete();     } }  // 7. 主程序集成 var builder = WebApplication.CreateBuilder(); builder.Services.AddSingleton<BiometricProcessor>();  var app = builder.Build();  // 生物特征识别端点 app.MapPost("/biometric", async (byte[] imageData, BiometricProcessor processor) => {     var result = await processor.ProcessFrameAsync(imageData);     return Results.Ok(result); });  app.Run();  // 8. 辅助类 public record BiometricFrame(byte[] ImageData); public class BiometricResult {     public float InfraredScore { get; set; }  // 红外特征强度(0-1)     public bool HasPalmVein { get; set; }    // 是否检测到掌静脉     public float FingerprintScore { get; set; } // 指纹匹配度(0-1)     public bool HasMask { get; set; }        // 是否戴口罩     public IrisRecognitionResult IrisResult { get; set; } // 新增虹膜识别结果 }  // 虹膜识别结果结构 public record IrisRecognitionResult(bool Detected, float MatchScore);  // 更新ProcessFrameAsync方法 public async Task<BiometricResult> ProcessFrameAsync(byte[] imageData) {     using var mat = Mat.FromImageData(imageData);     var result = _resultPool.Get();          try {         // 红外检测         result.InfraredScore = DetectInfrared(mat);                  // 掌静脉识别         result.HasPalmVein = DetectPalmVein(mat);                  // 口罩检测         result.HasMask = DetectMask(mat);                  return result;     }     finally {         _resultPool.Return(result);     } }  // 辅助方法：眼睛检测（优化版） private Rect[] DetectEyes(Mat faceImage) {     using var gray = new Mat();     Cv2.CvtColor(faceImage, gray, ColorConversionCodes.BGR2GRAY);     Cv2.EqualizeHist(gray, gray);  // 直方图均衡化提升检测效果          return _eyeClassifier.DetectMultiScale(gray, 1.1, 3,          HaarDetectionTypes.ScaleImage,          new Size(30, 30)); }  public async ValueTask DisposeAsync() {     _cts.Cancel();     _processingChannel.Writer.Complete(); }
